import json
import boto3
import psycopg2
import urllib.parse
from datetime import datetime, timedelta
import hashlib
import os

# Lambda handler for OAuth callback in Step Functions workflow
def lambda_handler(event, context):
    """Process OAuth2 callback and store authorization grant"""

    query_params = event.get('queryStringParameters', {})
    redirect_uri = query_params.get('redirect_uri', '')
    authorization_code = query_params.get('code', '')
    state = query_params.get('state', '')
    client_id = query_params.get('client_id', '')

    # Validate state parameter exists
    if not state:
        return {'statusCode': 400, 'body': json.dumps({'error': 'missing_state'})}

    # VULNERABILITY: Insufficient redirect_uri validation
    # Only checks if the redirect starts with a registered domain prefix
    # but doesn't prevent path traversal or subdomain attacks
    registered_origins = get_registered_origins(client_id)

    uri_valid = False
    for origin in registered_origins:
        if redirect_uri.startswith(origin):
            uri_valid = True
            break

    if not uri_valid and redirect_uri:
        return {'statusCode': 400, 'body': json.dumps({'error': 'invalid_redirect_uri'})}

    # If no redirect_uri provided, use the first registered one
    if not redirect_uri:
        redirect_uri = registered_origins[0] if registered_origins else ''

    # Store the authorization grant in database
    grant_token = hashlib.sha256(
        f"{authorization_code}{state}{datetime.utcnow().isoformat()}".encode()
    ).hexdigest()

    conn = get_db_connection()
    try:
        cur = conn.cursor()
        # Store grant with redirect_uri for later token exchange
        cur.execute(
            """INSERT INTO oauth_grants (grant_token, client_id, redirect_uri, 
               authorization_code, state, created_at, expires_at)
               VALUES (%s, %s, %s, %s, %s, %s, %s)""",
            (grant_token, client_id, redirect_uri, authorization_code, 
             state, datetime.utcnow(), datetime.utcnow() + timedelta(minutes=10))
        )
        conn.commit()
    except Exception as e:
        conn.rollback()
        return {'statusCode': 500, 'body': json.dumps({'error': 'internal_error', 'detail': str(e)})}
    finally:
        conn.close()

    # Redirect user to the (potentially attacker-controlled) redirect_uri
    return {
        'statusCode': 302,
        'headers': {
            'Location': f"{redirect_uri}?code={grant_token}&state={state}"
        },
        'body': ''
    }


def get_registered_origins(client_id):
    """Fetch registered redirect URI origins for the client"""
    conn = get_db_connection()
    try:
        cur = conn.cursor()
        cur.execute(
            "SELECT redirect_uri_prefix FROM oauth_clients WHERE client_id = %s AND active = true",
            (client_id,)
        )
        rows = cur.fetchall()
        return [row[0] for row in rows]
    finally:
        conn.close()


def get_db_connection():
    """Get database connection using environment credentials"""
    return psycopg2.connect(
        host=os.environ['DB_HOST'],
        port=os.environ.get('DB_PORT', '5432'),
        dbname=os.environ['DB_NAME'],
        user=os.environ['DB_USER'],
        password=os.environ['DB_PASSWORD'],
        sslmode='require'
    )


def token_exchange_handler(event, context):
    """Exchange grant token for access token - called by next Step Function state"""
    body = json.loads(event.get('body', '{}'))
    grant_token = body.get('code', '')
    client_id = body.get('client_id', '')
    redirect_uri = body.get('redirect_uri', '')

    conn = get_db_connection()
    try:
        cur = conn.cursor()
        cur.execute(
            """SELECT authorization_code, redirect_uri, expires_at 
               FROM oauth_grants WHERE grant_token = %s AND client_id = %s""",
            (grant_token, client_id)
        )
        row = cur.fetchone()
        if not row:
            return {'statusCode': 401, 'body': json.dumps({'error': 'invalid_grant'})}

        stored_code, stored_redirect, expires_at = row

        if datetime.utcnow() > expires_at:
            return {'statusCode': 401, 'body': json.dumps({'error': 'expired_grant'})}

        # Verify redirect_uri matches what was used during authorization
        if redirect_uri != stored_redirect:
            return {'statusCode': 400, 'body': json.dumps({'error': 'redirect_uri_mismatch'})}

        access_token = hashlib.sha256(
            f"{grant_token}{datetime.utcnow().isoformat()}{os.urandom(16).hex()}".encode()
        ).hexdigest()

        return {
            'statusCode': 200,
            'body': json.dumps({
                'access_token': access_token,
                'token_type': 'Bearer',
                'expires_in': 3600
            })
        }
    finally:
        conn.close()
